import io
import csv
from fastapi import APIRouter, Response
from app.services.db_manager import load_reviews_from_db
from app.routers.home import get_home_dashboard
from app.services.bedrock_advisor import get_bedrock_executive_report

router = APIRouter(prefix="/api/reports", tags=["Reports"])

@router.post("/generate")
def generate_report():
    home_data = get_home_dashboard()
    report = get_bedrock_executive_report(home_data)
    return {
        "title": "British Airways Executive Customer Intelligence Report",
        "subtitle": "Generated by SkyPulse AI Engine powered by Amazon Bedrock",
        "date": "2024-07-31",
        "author": "SkyPulse Advisory Board",
        "summary": report
    }

@router.get("/export-csv")
def export_csv():
    reviews = load_reviews_from_db()
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["ID", "Title", "Text", "Sentiment", "Confidence", "Emotion", "CSI Score", "Primary Touchpoint", "Airport", "Region", "Date"])

    for r in reviews:
        writer.writerow([
            r.get("id"),
            r.get("title"),
            r.get("text"),
            r.get("sentiment"),
            r.get("confidence"),
            r.get("emotion"),
            r.get("csi_score"),
            r.get("primary_touchpoint"),
            r.get("airport"),
            r.get("region"),
            r.get("date")
        ])

    res = Response(content=output.getvalue(), media_type="text/csv")
    res.headers["Content-Disposition"] = "attachment; filename=skypulse_ba_customer_intelligence.csv"
    return res
